-- ── Query 1 ────────────────────────────────────────────────────────────
SELECT     TRUNC(SYSDATE)                                        AS REPORT_DATE,     oh.ORDER_NO                                           AS PO_NUMBER,     oh.SUPPLIER                                           AS SUPPLIER_ID,     sp.SUP_NAME                                           AS SUPPLIER_NAME,     ol.ITEM                                               AS ITEM_ID,     im.ITEM_DESC                                          AS ITEM_DESCRIPTION,     im.DEPT                                               AS DEPT_NO,     ol.LOCATION                                           AS LOCATION_ID,     ol.QTY_ORDERED                                        AS QTY_ORDERED,     ol.UNIT_COST                                          AS ITEM_UNIT_COST,     ROUND(ol.QTY_ORDERED * ol.UNIT_COST,2)                AS TOTAL_COST_FOR_ITEM_IN_PO,     ROUND(         SUM(ol.QTY_ORDERED * ol.UNIT_COST) OVER (PARTITION BY oh.ORDER_NO),         2     )                                                      AS TOTAL_COST_FOR_PO,     isc.UNIT_COST                                         AS SUPPLIER_BASE_COST,     ils.AV_COST                                           AS WEIGHTED_AVG_COST FROM  MFCS_RDS.RDS_WV_ORDHEAD                 oh JOIN  MFCS_RDS.RDS_WV_ORDLOC                  ol   ON oh.ORDER_NO = ol.ORDER_NO JOIN  MFCS_RDS.RDS_WV_ITEM_MASTER             im   ON ol.ITEM     = im.ITEM LEFT JOIN MFCS_RDS.RDS_WV_SUPS                sp   ON oh.SUPPLIER = sp.SUPPLIER LEFT JOIN MFCS_RDS.RDS_WV_ITEM_SUPP_COUNTRY   isc  ON ol.ITEM     = isc.ITEM AND oh.SUPPLIER = isc.SUPPLIER AND isc.PRIMARY_SUPP_IND='Y'  AND isc.PRIMARY_COUNTRY_IND='Y' LEFT JOIN MFCS_RDS.RDS_WV_ITEM_LOC_SOH        ils  ON ol.ITEM     = ils.ITEM AND ol.LOCATION = ils.LOC WHERE     oh.STATUS  = 'A'          AND oh.WRITTEN_DATE BETWEEN ADD_MONTHS(SYSDATE,-3) AND TRUNC(SYSDATE) ORDER BY oh.ORDER_NO, ol.ITEM </ds:dbquery><ds:target_type>Oracle 12c</ds:target_type><ds:object_name/></ds:dataptr><ds:columns><ds:column><ds:name>REPORT_DATE</ds